import pytest
from validators import validate_email, validate_age, validate_username


# --- validate_email ---

def test_email_valid() -> None:
    assert validate_email("User@Example.COM") == "user@example.com"


def test_email_strips_whitespace() -> None:
    assert validate_email("  a@b.com  ") == "a@b.com"


def test_email_no_at_raises() -> None:
    with pytest.raises(ValueError, match="@"):
        validate_email("nodomain")


def test_email_multiple_at_raises() -> None:
    with pytest.raises(ValueError):
        validate_email("a@b@c.com")


def test_email_empty_local_raises() -> None:
    with pytest.raises(ValueError, match="local part"):
        validate_email("@domain.com")


def test_email_no_dot_in_domain_raises() -> None:
    with pytest.raises(ValueError, match="domain"):
        validate_email("user@nodot")


def test_email_domain_starts_with_dot_raises() -> None:
    with pytest.raises(ValueError):
        validate_email("user@.example.com")


def test_email_domain_ends_with_dot_raises() -> None:
    with pytest.raises(ValueError):
        validate_email("user@example.com.")


# --- validate_age ---

def test_age_valid_zero() -> None:
    assert validate_age(0) == 0


def test_age_valid_150() -> None:
    assert validate_age(150) == 150


def test_age_valid_middle() -> None:
    assert validate_age(30) == 30


def test_age_negative_raises() -> None:
    with pytest.raises(ValueError):
        validate_age(-1)


def test_age_over_150_raises() -> None:
    with pytest.raises(ValueError):
        validate_age(151)


def test_age_non_integer_raises() -> None:
    with pytest.raises(ValueError, match="integer"):
        validate_age(25.0)  # type: ignore[arg-type]


# --- validate_username ---

def test_username_valid() -> None:
    assert validate_username("alice") == "alice"


def test_username_valid_with_symbols() -> None:
    assert validate_username("cool-user_99") == "cool-user_99"


def test_username_min_length() -> None:
    assert validate_username("abc") == "abc"


def test_username_max_length() -> None:
    assert validate_username("a" * 20) == "a" * 20


def test_username_too_short_raises() -> None:
    with pytest.raises(ValueError, match="3"):
        validate_username("ab")


def test_username_too_long_raises() -> None:
    with pytest.raises(ValueError):
        validate_username("a" * 21)


def test_username_invalid_char_raises() -> None:
    with pytest.raises(ValueError, match="only contain"):
        validate_username("bad name")


def test_username_starts_with_underscore_raises() -> None:
    with pytest.raises(ValueError, match="start or end"):
        validate_username("_badstart")


def test_username_ends_with_hyphen_raises() -> None:
    with pytest.raises(ValueError):
        validate_username("badend-")


def test_username_empty_raises() -> None:
    with pytest.raises(ValueError):
        validate_username("")
